selector_to_html = {"a[href=\"e2e-use-case.html#qwen3-training-test\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. Qwen3 Training Test<a class=\"headerlink\" href=\"#qwen3-training-test\" title=\"Link to this heading\">#</a></h2><p>Requires 4 GPUs. The <code class=\"docutils literal notranslate\"><span class=\"pre\">te_fl_prefer</span></code> parameter controls backend selection \u2014 use <code class=\"docutils literal notranslate\"><span class=\"pre\">vendor</span></code> for vendor-specific implementations or <code class=\"docutils literal notranslate\"><span class=\"pre\">reference</span></code> for pure PyTorch fallback.</p>", "a[href=\"custom-backend-registration.html#out-of-tree-approach-plugin-package\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Out-of-tree Approach (Plugin Package)<a class=\"headerlink\" href=\"#out-of-tree-approach-plugin-package\" title=\"Link to this heading\">#</a></h2><h3>Plugin Package Structure<a class=\"headerlink\" href=\"#plugin-package-structure\" title=\"Link to this heading\">#</a></h3>", "a[href=\"custom-backend-registration.html#expected-output\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Expected Output<a class=\"headerlink\" href=\"#expected-output\" title=\"Link to this heading\">#</a></h2><p>When running, you should see logs like:</p>", "a[href=\"multi-platform-testing.html#install-the-flagos-compiler-and-operator-library\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. Install the FlagOS compiler and operator library<a class=\"headerlink\" href=\"#install-the-flagos-compiler-and-operator-library\" title=\"Link to this heading\">#</a></h2><p>TransformerEngine-FL\u2019s FlagOS tier is built on FlagGems, which in turn needs FlagTree as its compiler. Install both before enabling <code class=\"docutils literal notranslate\"><span class=\"pre\">te_fl_prefer:</span> <span class=\"pre\">flagos</span></code>.</p>", "a[href=\"multi-platform-testing.html#build-and-install-transformerengine-fl\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Build and install TransformerEngine-FL<a class=\"headerlink\" href=\"#build-and-install-transformerengine-fl\" title=\"Link to this heading\">#</a></h2><p>On NVIDIA, build against the CUDA toolkit:</p>", "a[href=\"multi-platform-testing.html#known-issues-and-workarounds\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">9. Known issues and workarounds<a class=\"headerlink\" href=\"#known-issues-and-workarounds\" title=\"Link to this heading\">#</a></h2><h3>9.1 MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">ImportError:</span> <span class=\"pre\">cannot</span> <span class=\"pre\">import</span> <span class=\"pre\">name</span> <span class=\"pre\">'AttrsDescriptor'</span> <span class=\"pre\">from</span> <span class=\"pre\">'triton.compiler.compiler'</span></code></strong> \u2014 PyTorch\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._inductor</span></code> imports <code class=\"docutils literal notranslate\"><span class=\"pre\">AttrsDescriptor</span></code> from Triton, which FlagTree does not provide. Add a compatibility shim to <code class=\"docutils literal notranslate\"><span class=\"pre\">/opt/conda/lib/python3.12/site-packages/triton/compiler/compiler.py</span></code>:</p>", "a[href=\"multi-platform-testing.html#run-the-qwen3-training-test\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">7. Run the Qwen3 training test<a class=\"headerlink\" href=\"#run-the-qwen3-training-test\" title=\"Link to this heading\">#</a></h2><p>The test job is a Qwen3 training run driven by FlagScale, with TransformerEngine-FL supplying the transformer operators.</p><p>First prepare the dataset and tokenizer:</p>", "a[href=\"e2e-use-case.html#prepare-megatron-lm-fl\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Prepare Megatron-LM-FL<a class=\"headerlink\" href=\"#prepare-megatron-lm-fl\" title=\"Link to this heading\">#</a></h2>", "a[href=\"custom-backend-registration.html#quick-start\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Quick Start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2>", "a[href=\"multi-platform-testing.html#platform-prerequisites\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Platform prerequisites<a class=\"headerlink\" href=\"#platform-prerequisites\" title=\"Link to this heading\">#</a></h2>", "a[href=\"custom-backend-registration.html#in-tree-approach-3-steps\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">In-tree Approach (3 Steps)<a class=\"headerlink\" href=\"#in-tree-approach-3-steps\" title=\"Link to this heading\">#</a></h2>", "a[href=\"multi-platform-testing.html#prepare-the-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Prepare the environment<a class=\"headerlink\" href=\"#prepare-the-environment\" title=\"Link to this heading\">#</a></h2><h3>3.1 Get the image and start the container<a class=\"headerlink\" href=\"#get-the-image-and-start-the-container\" title=\"Link to this heading\">#</a></h3><p>Go to the <a class=\"reference external\" href=\"https://flagos.io/Home\">FlagOS main page</a>, pick the image for your hardware from the download list in the middle of the page, and follow the on-page instructions to pull the image, enter the container, and start it.</p><p>Before installing the packages below, check inside the container that your device is visible (section 2 lists the command for each platform).</p>", "a[href=\"#user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1>", "a[href=\"e2e-use-case.html#prepare-transformerengine-fl\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Prepare TransformerEngine-FL<a class=\"headerlink\" href=\"#prepare-transformerengine-fl\" title=\"Link to this heading\">#</a></h2>", "a[href=\"multi-platform-testing.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-Platform Build and Testing<a class=\"headerlink\" href=\"#multi-platform-build-and-testing\" title=\"Link to this heading\">#</a></h1><p>This guide covers building TransformerEngine-FL and validating it with an end-to-end training workflow across CUDA (NVIDIA), MetaX, Hygon, Ascend, and T-Head PPU. It focuses on the parts that are specific to this component \u2014 the operator backend tiers, the vendor backends, and the attention backends \u2014 and on how to tell a healthy build from a broken one.</p><p>For the training orchestration around it, see <a class=\"reference external\" href=\"https://github.com/flagos-ai/Megatron-LM-FL\">Megatron-LM-FL</a> and <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagScale\">FlagScale</a>.</p>", "a[href=\"custom-backend-registration.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">TE-FL Custom Backend Examples<a class=\"headerlink\" href=\"#te-fl-custom-backend-examples\" title=\"Link to this heading\">#</a></h1><p>This directory contains examples demonstrating two ways to add custom backends.</p>", "a[href=\"multi-platform-testing.html#notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">10. Notes<a class=\"headerlink\" href=\"#notes\" title=\"Link to this heading\">#</a></h2>", "a[href=\"e2e-use-case.html#prepare-dataset-and-tokenizer\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. Prepare Dataset and Tokenizer<a class=\"headerlink\" href=\"#prepare-dataset-and-tokenizer\" title=\"Link to this heading\">#</a></h2><h3>Dataset<a class=\"headerlink\" href=\"#dataset\" title=\"Link to this heading\">#</a></h3>", "a[href=\"e2e-use-case.html#prepare-flagscale\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Prepare FlagScale<a class=\"headerlink\" href=\"#prepare-flagscale\" title=\"Link to this heading\">#</a></h2>", "a[href=\"custom-backend-registration.html#environment-variables\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment Variables<a class=\"headerlink\" href=\"#environment-variables\" title=\"Link to this heading\">#</a></h2><h3>Backend Selection<a class=\"headerlink\" href=\"#backend-selection\" title=\"Link to this heading\">#</a></h3>", "a[href=\"custom-backend-registration.html#examples\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Examples<a class=\"headerlink\" href=\"#examples\" title=\"Link to this heading\">#</a></h2><h3>Prefer vendor backend<a class=\"headerlink\" href=\"#prefer-vendor-backend\" title=\"Link to this heading\">#</a></h3>", "a[href=\"custom-backend-registration.html#two-approaches\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Two Approaches<a class=\"headerlink\" href=\"#two-approaches\" title=\"Link to this heading\">#</a></h2>", "a[href=\"e2e-use-case.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">End-to-End Use Case: TransformerEngine-FL + Megatron-LM-FL + FlagScale<a class=\"headerlink\" href=\"#end-to-end-use-case-transformerengine-fl-megatron-lm-fl-flagscale\" title=\"Link to this heading\">#</a></h1><p>This guide walks through an end-to-end training workflow using TransformerEngine-FL, Megatron-LM-FL, and FlagScale together, performed on both CUDA (NVIDIA) and MetaX platforms.</p>", "a[href=\"multi-platform-testing.html#backend-layout\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Backend layout<a class=\"headerlink\" href=\"#backend-layout\" title=\"Link to this heading\">#</a></h2><p>TransformerEngine-FL dispatches every operator through three tiers. Knowing which tier a failure comes from is the fastest way to localize a problem.</p>", "a[href=\"e2e-use-case.html#deepseek-v3-training-test\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">7. DeepSeek-V3 Training Test<a class=\"headerlink\" href=\"#deepseek-v3-training-test\" title=\"Link to this heading\">#</a></h2><p>Requires 4 GPUs. Uses expert parallelism and per-operator backend configuration for grouped GEMM.</p>", "a[href=\"e2e-use-case.html#notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">8. Notes<a class=\"headerlink\" href=\"#notes\" title=\"Link to this heading\">#</a></h2>", "a[href=\"multi-platform-testing.html#run-the-deepseek-v3-training-test\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">8. Run the DeepSeek-V3 training test<a class=\"headerlink\" href=\"#run-the-deepseek-v3-training-test\" title=\"Link to this heading\">#</a></h2><p>Requires 4 GPUs. Uses expert parallelism and per-operator backend configuration for grouped GEMM.</p>", "a[href=\"multi-platform-testing.html#operator-selection\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. Operator selection<a class=\"headerlink\" href=\"#operator-selection\" title=\"Link to this heading\">#</a></h2><p>Operator selection is driven by three model arguments in the task-level YAML:</p>", "a[href=\"e2e-use-case.html#docker-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Docker Environment<a class=\"headerlink\" href=\"#docker-environment\" title=\"Link to this heading\">#</a></h2><h3>FlagOS Release Image (v0.2.0-rc2, Recommended)<a class=\"headerlink\" href=\"#flagos-release-image-v0-2-0-rc2-recommended\" title=\"Link to this heading\">#</a></h3><p>Includes torch 2.4.0a0, triton 3.0.0, trans-engine 2.14.0. Suitable for 100B+ parameter model pre-training.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
